    fn drop(&mut self) {
        {
            let mut permits: MutexGuard<'_, usize> = self
                .semaphore
                .permits
                .lock()
                .unwrap_or_else(|e| e.into_inner());
            *permits += 1;
        }
        self.semaphore.available.notify_one();
    }
}

